#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <limits.h>

static void sort(int *a,int n){
    for(int i=1;i<n;++i){
        int value=a[i],j=i;
        while(j>0 && a[j-1]>value){a[j]=a[j-1];--j;}
        a[j]=value;
    }
}
int main(void) {
int a[256]; int n;
if (scanf("%d", &n)!=1 || n<0 || n>256) return 1;
for(int i=0;i<n;++i) if(scanf("%d", &a[i])!=1) return 1;
sort(a,n);
for(int i=0;i<n;++i) printf("%s%d", i?" ":"",a[i]); puts("");
return 0;
}

